import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"隐私选择","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy-choices.md","filePath":"zh-CN/guide/privacy-choices.md","lastUpdated":1795170900000}'),i={name:"zh-CN/guide/privacy-choices.md"};function h(c,a,l,n,s,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="隐私选择" tabindex="-1">隐私选择 <a class="header-anchor" href="#隐私选择" aria-label="Permalink to &quot;隐私选择&quot;">​</a></h1><p>几个简单的方法，让你自己掌控。</p><h2 id="无痕浏览" tabindex="-1">无痕浏览 <a class="header-anchor" href="#无痕浏览" aria-label="Permalink to &quot;无痕浏览&quot;">​</a></h2><p>使用无痕窗口（⌘⇧N）。它不会写入历史记录或记住会话，关闭后标签页即消失。</p><h2 id="清除已存内容" tabindex="-1">清除已存内容 <a class="header-anchor" href="#清除已存内容" aria-label="Permalink to &quot;清除已存内容&quot;">​</a></h2><p>在设置的 Cookie 管理器里删除 Cookie 和网站数据。历史记录和下载记录也可以在同一处清除。</p><h2 id="决定每个网站能做什么" tabindex="-1">决定每个网站能做什么 <a class="header-anchor" href="#决定每个网站能做什么" aria-label="Permalink to &quot;决定每个网站能做什么&quot;">​</a></h2><p>摄像头、麦克风和文件权限按网站分别记住。在设置里允许你信任的网站、拒绝其他网站。弹窗只对你允许的网站开放。</p><h2 id="控制后台功能" tabindex="-1">控制后台功能 <a class="header-anchor" href="#控制后台功能" aria-label="Permalink to &quot;控制后台功能&quot;">​</a></h2><p>在设置里随时开关广告拦截订阅。关闭后不会拉取任何规则。</p><h2 id="选择搜索引擎" tabindex="-1">选择搜索引擎 <a class="header-anchor" href="#选择搜索引擎" aria-label="Permalink to &quot;选择搜索引擎&quot;">​</a></h2><p>在设置里指定默认搜索引擎，搜索建议来自你选择的引擎。</p><h2 id="有疑问" tabindex="-1">有疑问 <a class="header-anchor" href="#有疑问" aria-label="Permalink to &quot;有疑问&quot;">​</a></h2><p>想了解更多数据处理方式，请写信到 <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',14)])])}const _=e(i,[["render",h]]);export{u as __pageData,_ as default};
